    );
    $block='<section data-se-battery400-offers-v1="1" aria-labelledby="se-battery400-offer-title" style="margin:22px 0;padding:clamp(16px,4vw,24px);background:#eff8f5;color:#142e2b;border:1px solid #c9ddd9;border-radius:16px;line-height:1.6"><p style="margin:0;color:#205d53;font-weight:700;font-size:.85em;text-transform:uppercase">Nákupní výběr · 400 Wp</p><h2 id="se-battery400-offer-title" style="margin:8px 0;color:#142e2b">Dvě konkrétní baterie k 400W panelu: kterou prověřit?</h2><p><strong>Pro stávající 12V sestavu zvažte 12,8V baterii, pro kompatibilní 24V systém větší 25,6V variantu.</strong> Obě jsou 100Ah LiFePO₄, ale druhá má dvojnásobnou nominální energii. Jsou to kandidáti ke kontrole, nikoli potvrzená kompatibilita s libovolným panelem, MPPT nebo měničem.</p><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:12px">';
    foreach($rows as $r) {
        $target='https://www.vselektro.eu/'.$r[3]; $href=$target;
